ruleContent.nextContentUrl:
@js:

var r=java.ajax("https://m.sm.cn/api/rest?method=sc.novel_authorized&q={{$..bookName}}&source=纵横中文网");
var hz=/&fr=.*?(?=")/.exec(r)[0];
baseUrl=baseUrl.replace(/&fr=.*/,hz);
r=java.ajax(baseUrl);
var cn=/chapterNum":(\d+)/.exec(r)[1];
var pc=/pageCount":(\d+)/.exec(r)[1];
var ncid=/nextChapterId":"(.*?)"/.exec(r)[1];

if(cn<pc)
baseUrl=baseUrl.replace(/chapterId=\d+_?\d*/,'chapterId='+ncid);

